#!/usr/bin/env bash
set -euo pipefail
set +x; umask 077
unset BASH_XTRACEFD 2>/dev/null || true
unset NODE_OPTIONS NODE_PATH NODE_DEBUG NODE_DEBUG_NATIVE NODE_EXTRA_CA_CERTS NODE_TLS_REJECT_UNAUTHORIZED \
  SSL_CERT_FILE SSL_CERT_DIR OPENSSL_CONF OPENSSL_ENGINES SSLKEYLOGFILE RES_OPTIONS LOCALDOMAIN HOSTALIASES \
  LD_PRELOAD LD_LIBRARY_PATH DYLD_INSERT_LIBRARIES DYLD_LIBRARY_PATH \
  HTTP_PROXY HTTPS_PROXY ALL_PROXY NO_PROXY http_proxy https_proxy all_proxy no_proxy
for inherited_name in ${!FOUNDRY_@} ${!CAST_@}; do unset "$inherited_name"; done
export RUST_BACKTRACE=0 RUST_LIB_BACKTRACE=0
ulimit -c 0 || { echo 'cannot disable core dumps' >&2; exit 1; }
export PATH=/home/leonardov/.foundry/bin:/home/leonardov/.local/toolchains/node-v24.19.0-linux-x64/bin:/usr/bin:/bin
test $# -eq 0 && test -t 0 && test -t 1 || { echo 'pilot gate emergency cancel requires interactive terminal and no arguments' >&2; exit 64; }
: "${USDOM_CONTROL_EVIDENCE_DIRECTORY:?required}" "${USDOM_MAINNET_PREFLIGHT_RPC_SOURCES_FILE:?required}" "${USDOM_SAFE_PACKAGE:?required}" "${USDOM_ONEKEY_IOS_WALLETCONNECT_CONFIG:?required}"
readonly project=/home/leonardov/usdom-security-audit-20261015/implementation-dom-protocol/labs/usdom-reserve
test -d "$USDOM_CONTROL_EVIDENCE_DIRECTORY" && test ! -L "$USDOM_CONTROL_EVIDENCE_DIRECTORY"
test "$(stat -c '%u:%a' -- "$USDOM_CONTROL_EVIDENCE_DIRECTORY")" = "$UID:700"
test "$(realpath -e "$USDOM_CONTROL_EVIDENCE_DIRECTORY")" = "$USDOM_CONTROL_EVIDENCE_DIRECTORY"
for fd_path in /proc/"$$"/fd/*; do inherited_fd=${fd_path##*/}; [[ $inherited_fd =~ ^[0-9]+$ ]] || exit 1; (( inherited_fd<=2 )) && continue; [[ $inherited_fd == 255 ]] && continue; exec {inherited_fd}>&-; done
cd "$project"; exec 9<"$USDOM_CONTROL_EVIDENCE_DIRECTORY"; flock -n 9 || exit 75
test "$(realpath -e /proc/$$/fd/9)" = "$USDOM_CONTROL_EVIDENCE_DIRECTORY"
readonly evidence_parent_identity=$(stat -Lc '%d:%i:%u:%a' -- /proc/$$/fd/9)
test "$evidence_parent_identity" = "$(stat -c '%d:%i:%u:%a' -- "$USDOM_CONTROL_EVIDENCE_DIRECTORY")"
[[ $evidence_parent_identity == *":$UID:700" ]]
assert_evidence_parent() {
 test -d "$USDOM_CONTROL_EVIDENCE_DIRECTORY" && test ! -L "$USDOM_CONTROL_EVIDENCE_DIRECTORY"
 test "$(realpath -e "$USDOM_CONTROL_EVIDENCE_DIRECTORY")" = "$USDOM_CONTROL_EVIDENCE_DIRECTORY"
 test "$(stat -c '%d:%i:%u:%a' -- "$USDOM_CONTROL_EVIDENCE_DIRECTORY")" = "$evidence_parent_identity"
 test "$(stat -Lc '%d:%i:%u:%a' -- /proc/$$/fd/9)" = "$evidence_parent_identity"
}
readonly release="$project/config/proof-reserve.unconfigured.json" gate="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-plan.json" role=guardian
readonly plan="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-plan.json" sig1="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-signature-1.json" sig2="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-signature-2.json"
readonly sighex1="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-onekey-signature-1.hex" sighex2="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-onekey-signature-2.hex" relayer_policy="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-gate-relayer-policy.json" relayer_envelope="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-relayer-envelope.json"
readonly package="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-transaction.json" raw="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-raw.txt" receipt="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-receipt.json" completion="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-finalized.json"
for file in "$gate" "$release" "$USDOM_SAFE_PACKAGE"; do test -f "$file" && test ! -L "$file" && test "$(stat -c '%u:%a:%h' "$file")" = "$UID:600:1"; done
for file in "$plan" "$sig1" "$sig2" "$sighex1" "$sighex2" "$package" "$relayer_envelope" "$raw" "$receipt" "$completion"; do if test -e "$file" || test -L "$file"; then test -f "$file" && test ! -L "$file" && test "$(stat -c '%u:%a:%h' "$file")" = "$UID:600:1"; fi; done
for authority in "$gate" "$release" "$USDOM_SAFE_PACKAGE"; do node scripts/check-private-strict-json-file.mjs "$authority"; done
for authority in "$plan" "$sig1" "$sig2" "$package" "$receipt" "$completion"; do if test -e "$authority"; then node scripts/check-private-strict-json-file.mjs "$authority"; fi; done
node scripts/check-direct-strict-json-file.mjs "$USDOM_MAINNET_PREFLIGHT_RPC_SOURCES_FILE"
test "$(jq -er 'length' "$USDOM_MAINNET_PREFLIGHT_RPC_SOURCES_FILE")" -ge 2; reserve=$(jq -er .reserve "$release"); safe=$(jq -er .guardian "$release")
tmp=$(mktemp -d -p /dev/shm usdom-pilot-cancel.XXXXXXXX)
tmp_identity=$(/usr/bin/stat -c '%u:%d:%i:%a' "$tmp")
pilot_cancel_broadcast_state=clean
cleanup() {
 local status=${1:-$?}
 trap - EXIT HUP INT TERM
 if [[ $pilot_cancel_broadcast_state != clean ]] && (( status != 0 )); then status=80; fi
 if [[ $(/usr/bin/stat -c '%u:%d:%i:%a' "$tmp" 2>/dev/null) == "$tmp_identity" ]]; then
  /usr/bin/rm -rf -- "$tmp" || { (( status != 0 )) || status=1; }
 else
  (( status != 0 )) || status=1
 fi
 exit "$status"
}
trap 'cleanup $?' EXIT
trap 'cleanup 129' HUP
trap 'cleanup 130' INT
trap 'cleanup 143' TERM
node scripts/materialize-private-foundry-rpc-aliases.mjs "$USDOM_MAINNET_PREFLIGHT_RPC_SOURCES_FILE" config/mainnet-preflight-rpc-catalog.json >"$tmp/foundry-rpc.toml"
chmod 0600 "$tmp/foundry-rpc.toml"; export FOUNDRY_CONFIG="$tmp/foundry-rpc.toml"
rpcs=(usdom_rpc_a usdom_rpc_b)
rpc1=${rpcs[0]}; rpc2=${rpcs[1]}
observe(){ local rpc=$1 out=$2 n h; test "$(cast chain-id --rpc-url "$rpc")" = 1; n=$(cast block finalized --field number --rpc-url "$rpc"); h=$(cast block "$n" --field hash --rpc-url "$rpc"|tr '[:upper:]' '[:lower:]'); jq -cn --arg chainId 1 --arg finalizedBlockNumber "$n" --arg finalizedBlockHash "$h" --arg safeNonce "$(cast call "$safe" 'nonce()(uint256)' --block "$n" --rpc-url "$rpc")" --arg authorization "$(cast call "$reserve" 'authorizedPilotDeposit()(bytes32)' --block "$n" --rpc-url "$rpc"|tr '[:upper:]' '[:lower:]')" --arg snapshot "$(cast call "$reserve" 'authorizedPilotSnapshot()(bytes32)' --block "$n" --rpc-url "$rpc"|tr '[:upper:]' '[:lower:]')" --arg validUntil "$(cast call "$reserve" 'authorizedPilotValidUntil()(uint64)' --block "$n" --rpc-url "$rpc")" --arg generation "$(cast call "$reserve" 'pilotAuthorizationGeneration()(uint64)' --block "$n" --rpc-url "$rpc")" '{chainId:$chainId,finalizedBlockNumber:$finalizedBlockNumber,finalizedBlockHash:$finalizedBlockHash,safeNonce:$safeNonce,authorization:$authorization,snapshot:$snapshot,validUntil:$validUntil,generation:$generation}' >"$out"; chmod 0600 "$out"; }
observe "$rpc1" "$tmp/a.json"; observe "$rpc2" "$tmp/b.json"; cmp -s "$tmp/a.json" "$tmp/b.json"
if test -e "$completion"; then
 for file in "$plan" "$sig1" "$sig2" "$package" "$relayer_envelope" "$raw" "$receipt"; do test -f "$file" && test ! -L "$file" && test "$(stat -c '%u:%a:%h' "$file")" = "$UID:600:1"; done
 node scripts/assemble-pilot-deposit-gate-cancel.mjs "$plan" "$sig1" "$sig2" | cmp -s - "$package"
else
 node scripts/prepare-pilot-deposit-gate-cancel-plan.mjs "$gate" "$release" "$USDOM_SAFE_PACKAGE" "$role" "$tmp/a.json" "$tmp/b.json" >"$tmp/plan.json"
 if test -e "$plan"; then test "$(jq -cS 'del(.finalizedBlockNumber,.finalizedBlockHash)' "$plan")" = "$(jq -cS 'del(.finalizedBlockNumber,.finalizedBlockHash)' "$tmp/plan.json")"; else assert_evidence_parent; node scripts/install-private-file-new-stdin.mjs --json "$plan" <"$tmp/plan.json"; fi
fi
safe_hash=$(jq -er .safeTxHash "$plan"); safe_nonce=$(jq -er .safeTransaction.nonce "$plan"); safe_data=$(jq -er .safeTransaction.data "$plan"); generation=$(jq -er .generation "$plan"); snapshot=$(jq -er .snapshotCommitment "$plan")
safe_hash_call=$(node scripts/prepare-private-safe-hash-eth-call.mjs "$plan" "$(jq -er .finalizedBlockNumber "$plan")")
for rpc in "$rpc1" "$rpc2"; do
 observed_hash=$(printf '%s
' "$safe_hash_call" | cast rpc eth_call --raw --rpc-url "$rpc" | jq -er '.|ascii_downcase')
 test "$observed_hash" = "$safe_hash"
done
assert_live(){ observe "$rpc1" "$tmp/live-a.json"; observe "$rpc2" "$tmp/live-b.json"; cmp -s "$tmp/live-a.json" "$tmp/live-b.json"; test "$(jq -er .safeNonce "$tmp/live-a.json")" = "$safe_nonce"; test "$(jq -er .authorization "$tmp/live-a.json")" = "$(jq -er .expectedAuthorization "$plan")"; test "$(jq -er .snapshot "$tmp/live-a.json")" = "$snapshot"; test "$(jq -er .generation "$tmp/live-a.json")" = "$generation"; }
node scripts/prepare-pilot-gate-onekey-envelope.mjs "$plan" >"$tmp/safe-envelope.json"; chmod 0600 "$tmp/safe-envelope.json"
sign(){ local index=$1 destination=$2 signature_file=$3 identity expected_owner observed_owner approval status physical request response; test ! -e "$destination" || return 0; test ! -e "$signature_file" || pilot_cancel_broadcast_state=signed-unresolved; identity="$USDOM_CONTROL_EVIDENCE_DIRECTORY/onekey-guardian-owner-$index-identity.json"; test -f "$identity" && test ! -L "$identity" && test "$(stat -c '%u:%a:%h' "$identity")" = "$UID:600:1"; expected_owner=$(jq -er ".authorizedOwners[$((index-1))]" "$plan"); observed_owner=$(jq -er .expectedAddress "$identity"); test "$observed_owner" = "$expected_owner"; assert_live; echo "EMERGENCY CANCEL REVIEW role=$role owner=$index/2 safe=$safe nonce=$safe_nonce reserve=$reserve snapshot=$snapshot generation=$generation safeTxHash=$safe_hash" >&2; read -r -p "Digite AUTORIZO CANCELAR GATE PILOTO OWNER $index HASH $safe_hash: " approval </dev/tty; test "$approval" = "AUTORIZO CANCELAR GATE PILOTO OWNER $index HASH $safe_hash"; assert_live; if test ! -e "$signature_file"; then physical="$USDOM_CONTROL_EVIDENCE_DIRECTORY/onekey-guardian-owner-$index-physical-account.json"; request="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-owner-$index-walletconnect-request.json"; response="$USDOM_CONTROL_EVIDENCE_DIRECTORY/pilot-deposit-gate-cancel-owner-$index-walletconnect-response.json"; test -f "$physical" && test ! -L "$physical" && test "$(stat -c '%u:%a:%h' "$physical")" = "$UID:600:1"; if test ! -e "$request"; then node scripts/prepare-onekey-ios-walletconnect-request.mjs "$USDOM_ONEKEY_IOS_WALLETCONNECT_CONFIG" "$tmp/safe-envelope.json" "$physical" "$expected_owner" "$request"; fi; node scripts/check-onekey-ios-walletconnect-request.mjs "$USDOM_ONEKEY_IOS_WALLETCONNECT_CONFIG" "$tmp/safe-envelope.json" "$physical" "$expected_owner" "$request"; if test ! -e "$response"; then if node scripts/sign-onekey-ios-walletconnect-typed-data.mjs "$USDOM_ONEKEY_IOS_WALLETCONNECT_CONFIG" "$request" "$physical" "$response"; then :; else status=$?; pilot_cancel_broadcast_state=signed-unresolved; ((status==80)) && exit 80; exit "$status"; fi; fi; pilot_cancel_broadcast_state=signed-unresolved; node scripts/extract-onekey-ios-walletconnect-signature.mjs "$request" "$response" >"$tmp/owner-$index.hex"; chmod 0600 "$tmp/owner-$index.hex"; node scripts/install-private-file-immutable-stdin.mjs "$signature_file" <"$tmp/owner-$index.hex"; fi; assert_evidence_parent; if node scripts/materialize-pilot-gate-onekey-signature.mjs "$plan" "$identity" "$signature_file" "$index" "$destination"; then :; else status=$?; pilot_cancel_broadcast_state=signed-unresolved; exit "$status"; fi; }
sign 1 "$sig1" "$sighex1"; sign 2 "$sig2" "$sighex2"; node scripts/assemble-pilot-deposit-gate-cancel.mjs "$plan" "$sig1" "$sig2" >"$tmp/package.json"; assert_evidence_parent; if test -e "$package"; then cmp -s "$tmp/package.json" "$package"; else node scripts/install-private-file-new-stdin.mjs --json "$package" <"$tmp/package.json"; fi
to=$(jq -er .to "$package"); data=$(jq -er .data "$package")
if test ! -e "$relayer_envelope"; then assert_live
 test -f "$relayer_policy" && test ! -L "$relayer_policy" && test "$(stat -c '%u:%a:%h' "$relayer_policy")" = "$UID:600:1"; node scripts/check-private-strict-json-file.mjs "$relayer_policy"
 relayer=$(jq -er .relayer "$relayer_policy"); for forbidden in "$(jq -er .token "$release")" "$(jq -er .reserve "$release")" "$(jq -er .governance "$release")" "$(jq -er .guardian "$release")"; do test "${relayer,,}" != "${forbidden,,}"; done; for owner in $(jq -er '.governanceOwners[],.guardianOwners[],.checkpointGuardianOwners[]' "$release"); do test "${relayer,,}" != "${owner,,}"; done
 nonce1=$(cast nonce "$relayer" --block pending --rpc-url "$rpc1"); test "$nonce1" = "$(cast nonce "$relayer" --block pending --rpc-url "$rpc2")"; test "$(cast code "$relayer" --block finalized --rpc-url "$rpc1")" = 0x; test "$(cast code "$relayer" --block finalized --rpc-url "$rpc2")" = 0x
 printf '{"to":"%s","data":"%s"}\n' "$to" "$data" >"$tmp/private-transaction-input.json"; chmod 0600 "$tmp/private-transaction-input.json"; private_estimate=$(node scripts/prepare-private-eth-estimate-gas.mjs "$tmp/private-transaction-input.json" "$relayer")
 gas_estimate=$(printf '%s\n' "$private_estimate" | cast rpc eth_estimateGas --raw --rpc-url "$rpc1" | jq -er . | xargs cast to-dec); test "$gas_estimate" = "$(printf '%s\n' "$private_estimate" | cast rpc eth_estimateGas --raw --rpc-url "$rpc2" | jq -er . | xargs cast to-dec)"; base=$(cast block finalized --field baseFeePerGas --rpc-url "$rpc1"); test "$base" = "$(cast block finalized --field baseFeePerGas --rpc-url "$rpc2")"; fee_plan=$(node scripts/calculate-pilot-transaction-fees.mjs "$gas_estimate" "$base" 500000 50000000000000000); gas=$(jq -er .gas <<<"$fee_plan"); fee=$(jq -er .maxFee <<<"$fee_plan")
 node scripts/prepare-pilot-gate-relayer-envelope.mjs "$tmp/private-transaction-input.json" "$package" "$relayer_policy" "$nonce1" "$gas" "$fee" 2000000000 >"$tmp/relayer-envelope.json"; chmod 0600 "$tmp/relayer-envelope.json"; assert_evidence_parent; node scripts/install-private-file-new-stdin.mjs --json "$relayer_envelope" <"$tmp/relayer-envelope.json"; echo "Envelope do relayer criado em $relayer_envelope. Instale a raw privada em $raw e execute novamente." >&2; exit 78
fi
if test ! -e "$raw"; then echo "raw privada do relayer ausente: $raw" >&2; exit 78; fi
node scripts/check-pilot-gate-relayer-raw.mjs "$raw" "$package" "$relayer_envelope" "$release" "$relayer_policy" >"$tmp/raw.json"; txhash=$(jq -er .transactionHash "$tmp/raw.json")
assert_relayer_live(){ local relayer nonce; relayer=$(jq -er .relayer "$relayer_envelope"); nonce=$(jq -er .nonce "$relayer_envelope"); test "$(cast nonce "$relayer" --block pending --rpc-url "$rpc1")" = "$nonce"; test "$(cast nonce "$relayer" --block pending --rpc-url "$rpc2")" = "$nonce"; test "$(cast code "$relayer" --block finalized --rpc-url "$rpc1")" = 0x; test "$(cast code "$relayer" --block finalized --rpc-url "$rpc2")" = 0x; node scripts/check-pilot-gate-relayer-raw.mjs "$raw" "$package" "$relayer_envelope" "$release" "$relayer_policy" | cmp -s - "$tmp/raw.json"; }
pilot_cancel_broadcast_state=signed-unresolved
if test ! -e "$receipt"; then if ! cast receipt "$txhash" --json --rpc-url "$rpc1" >"$tmp/r1.json" 2>/dev/null || ! cast receipt "$txhash" --json --rpc-url "$rpc2" >"$tmp/r2.json" 2>/dev/null; then assert_live; assert_relayer_live; read -r -p "Digite AUTORIZO TRANSMITIR CANCELAMENTO GATE TX $txhash: " approval </dev/tty; test "$approval" = "AUTORIZO TRANSMITIR CANCELAMENTO GATE TX $txhash"; assert_live; assert_relayer_live; assert_evidence_parent; pilot_cancel_broadcast_state=publishing; test "$(node scripts/publish-private-raw-transaction.mjs "$raw" "$USDOM_MAINNET_PREFLIGHT_RPC_SOURCES_FILE" config/mainnet-preflight-rpc-catalog.json 0|tr '[:upper:]' '[:lower:]')" = "$txhash"; fi; receipt_deadline=$((SECONDS+1800)); until cast receipt "$txhash" --json --rpc-url "$rpc1" >"$tmp/r1.json" 2>/dev/null && cast receipt "$txhash" --json --rpc-url "$rpc2" >"$tmp/r2.json" 2>/dev/null; do test "$SECONDS" -lt "$receipt_deadline" || { echo 'receipt observation timed out; restart to recover without rebroadcast' >&2; exit 75; }; sleep 12; done; assert_evidence_parent; node scripts/install-private-file-new-stdin.mjs --json "$receipt" <"$tmp/r1.json"; fi
for pair in "a:$rpc1" "b:$rpc2"; do label=${pair%%:*}; rpc=${pair#*:}; cast receipt "$txhash" --json --rpc-url "$rpc" >"$tmp/r-$label.json"; cast tx "$txhash" --json --rpc-url "$rpc" >"$tmp/t-$label.json"; done
test "$(jq -cS '{transactionHash,blockNumber,blockHash,transactionIndex,status,from,to,logs}' "$tmp/r-a.json")" = "$(jq -cS '{transactionHash,blockNumber,blockHash,transactionIndex,status,from,to,logs}' "$tmp/r-b.json")"; test "$(jq -cS '{transactionHash,blockNumber,blockHash,transactionIndex,status,from,to,logs}' "$receipt")" = "$(jq -cS '{transactionHash,blockNumber,blockHash,transactionIndex,status,from,to,logs}' "$tmp/r-a.json")"; test "$(jq -cS '{hash,from,to,nonce,input,value,blockNumber,blockHash}' "$tmp/t-a.json")" = "$(jq -cS '{hash,from,to,nonce,input,value,blockNumber,blockHash}' "$tmp/t-b.json")"
jq -e --arg tx "$txhash" '.status=="0x1" and (.transactionHash|ascii_downcase)==$tx' "$receipt" >/dev/null; jq -e --arg tx "$txhash" --arg from "$(jq -er '.from|ascii_downcase' "$tmp/raw.json")" --arg to "${safe,,}" --slurpfile package "$package" '(.hash|ascii_downcase)==$tx and (.from|ascii_downcase)==$from and (.to|ascii_downcase)==$to and (.input|ascii_downcase)==($package[0].data|ascii_downcase) and .value=="0x0"' "$tmp/t-a.json" >/dev/null
test "$(node scripts/canonical-uint256.mjs normalize "$(jq -er .nonce "$tmp/t-a.json")")" = "$(node scripts/canonical-uint256.mjs normalize "$(jq -er .nonce "$tmp/raw.json")")"
execution_topic=$(cast keccak 'ExecutionSuccess(bytes32,uint256)'|tr '[:upper:]' '[:lower:]'); cancel_topic=$(cast keccak 'PilotDepositAuthorizationCancelled(bytes32,bytes32,uint64,uint64,address)'|tr '[:upper:]' '[:lower:]'); event_data=$(cast abi-encode 'f(uint64,uint64)' "$(jq -er .validUntil "$plan")" "$generation"|tr '[:upper:]' '[:lower:]'); authority=0x000000000000000000000000${safe#0x}; authority=${authority,,}; jq -e --arg safe "${safe,,}" --arg execution "$execution_topic" --arg safeHash "$safe_hash" --arg reserve "${reserve,,}" --arg topic "$cancel_topic" --arg snapshot "$snapshot" --arg authorization "$(jq -er .expectedAuthorization "$plan")" --arg authority "$authority" --arg data "$event_data" '([.logs[]|select((.address|ascii_downcase)==$safe and (.topics[0]|ascii_downcase)==$execution and (.topics[1]|ascii_downcase)==$safeHash)]|length)==1 and ([.logs[]|select((.address|ascii_downcase)==$reserve and (.topics[0]|ascii_downcase)==$topic and (.topics[1]|ascii_downcase)==$snapshot and (.topics[2]|ascii_downcase)==$authorization and (.topics[3]|ascii_downcase)==$authority and (.data|ascii_downcase)==$data)]|length)==1' "$receipt" >/dev/null
block=$(node scripts/canonical-uint256.mjs normalize "$(jq -er .blockNumber "$receipt")"); block_hash=$(jq -er '.blockHash|ascii_downcase' "$receipt"); transaction_index=$(node scripts/canonical-uint256.mjs normalize "$(jq -er .transactionIndex "$receipt")"); finality_deadline=$((SECONDS+14400)); while :; do f1=$(cast block finalized --field number --rpc-url "$rpc1"); f2=$(cast block finalized --field number --rpc-url "$rpc2"); if test "$f1" = "$f2" && test "$(node scripts/canonical-uint256.mjs ge "$f1" "$block")" = true; then fh=$(cast block "$f1" --field hash --rpc-url "$rpc1"|tr '[:upper:]' '[:lower:]'); test "$fh" = "$(cast block "$f2" --field hash --rpc-url "$rpc2"|tr '[:upper:]' '[:lower:]')" && break; fi; test "$SECONDS" -lt "$finality_deadline" || { echo 'finality observation timed out; restart to recover without rebroadcast' >&2; exit 75; }; sleep 12; done
for pair in "a:$rpc1" "b:$rpc2"; do label=${pair%%:*}; rpc=${pair#*:}; cast receipt "$txhash" --json --rpc-url "$rpc" >"$tmp/post-finality-r-$label.json"; cast tx "$txhash" --json --rpc-url "$rpc" >"$tmp/post-finality-t-$label.json"; test "$(jq -cS '{transactionHash,blockNumber,blockHash,transactionIndex,status,from,to,logs}' "$tmp/post-finality-r-$label.json")" = "$(jq -cS '{transactionHash,blockNumber,blockHash,transactionIndex,status,from,to,logs}' "$receipt")"; test "$(jq -cS '{hash,from,to,nonce,input,value,blockNumber,blockHash}' "$tmp/post-finality-t-$label.json")" = "$(jq -cS '{hash,from,to,nonce,input,value,blockNumber,blockHash}' "$tmp/t-a.json")"; test "$(cast block "$block" --field hash --rpc-url "$rpc"|tr '[:upper:]' '[:lower:]')" = "$block_hash"; done
for rpc in "$rpc1" "$rpc2"; do test "$(cast block "$block" --field hash --rpc-url "$rpc"|tr '[:upper:]' '[:lower:]')" = "$block_hash"; test "$(cast call "$reserve" 'authorizedPilotDeposit()(bytes32)' --block "$f1" --rpc-url "$rpc")" = 0x$(printf '0%.0s' {1..64}); test "$(cast call "$reserve" 'authorizedPilotSnapshot()(bytes32)' --block "$f1" --rpc-url "$rpc")" = 0x$(printf '0%.0s' {1..64}); test "$(cast call "$reserve" 'authorizedPilotValidUntil()(uint64)' --block "$f1" --rpc-url "$rpc")" = 0; test "$(cast call "$reserve" 'pilotAuthorizationGeneration()(uint64)' --block "$f1" --rpc-url "$rpc")" = "$(node scripts/canonical-uint256.mjs add1 "$generation")"; done
if test -e "$completion"; then jq -e --arg tx "$txhash" --arg block "$block" --arg blockHash "$block_hash" --arg transactionIndex "$transaction_index" --arg snapshot "$snapshot" --arg generation "$generation" 'keys==["blockHash","blockNumber","finalizedBlockHash","finalizedBlockNumber","generation","schema","snapshotCommitment","transactionHash","transactionIndex"] and .schema=="usdom-pilot-deposit-gate-cancel-finalized/v2" and (.transactionHash|ascii_downcase)==$tx and .blockNumber==$block and (.blockHash|ascii_downcase)==$blockHash and .transactionIndex==$transactionIndex and (.snapshotCommitment|ascii_downcase)==$snapshot and .generation==$generation' "$completion" >/dev/null; stored=$(jq -er .finalizedBlockNumber "$completion"); stored_hash=$(jq -er '.finalizedBlockHash|ascii_downcase' "$completion"); for rpc in "$rpc1" "$rpc2"; do test "$(cast block "$stored" --field hash --rpc-url "$rpc"|tr '[:upper:]' '[:lower:]')" = "$stored_hash"; test "$(node scripts/canonical-uint256.mjs ge "$(cast block finalized --field number --rpc-url "$rpc")" "$stored")" = true; done; pilot_cancel_broadcast_state=clean; exit 0; fi
assert_evidence_parent
jq -n --arg tx "$txhash" --arg blockNumber "$block" --arg blockHash "$block_hash" --arg transactionIndex "$transaction_index" --arg finalizedBlockNumber "$f1" --arg finalizedBlockHash "$fh" --arg snapshot "$snapshot" --arg generation "$generation" '{schema:"usdom-pilot-deposit-gate-cancel-finalized/v2",transactionHash:$tx,blockNumber:$blockNumber,blockHash:$blockHash,transactionIndex:$transactionIndex,finalizedBlockNumber:$finalizedBlockNumber,finalizedBlockHash:$finalizedBlockHash,snapshotCommitment:$snapshot,generation:$generation}' | node scripts/install-private-file-new-stdin.mjs --json "$completion"
pilot_cancel_broadcast_state=clean
